for locale, strings in values.items():
    assert len(strings) == len(keys)
    path = Path(f'js/src/web/locales/{locale}-discovery.js')
    path.write_text('export const '+locale+'Discovery = '+json.dumps(dict(zip(('discovery.'+key for key in keys),strings)),ensure_ascii=False,indent=2)+';\n')
    target = Path(f'js/src/web/locales/{locale}-vacancy.js')
    text = target.read_text()
    if f'{locale}-discovery' not in text:
        text = f"import {{ {locale}Discovery }} from './{locale}-discovery.js';\n" + text
        text = text.replace(f'export const {locale}Vacancy = {{', f'export const {locale}Vacancy = {{\n  ...{locale}Discovery,')
        target.write_text(text)
